/**
 * 环形缓冲区
 * 高效存储时序传感器数据，避免频繁内存分配
 */

export default class RingBuffer {
  /**
   * 构造函数
   * @param {number} capacity - 缓冲区容量
   */
  constructor(capacity) {
    this.capacity = capacity
    this.buffer = new Array(capacity)
    this.head = 0      // 写入位置
    this.tail = 0      // 读取位置
    this.size = 0      // 当前大小
    this.isFull = false
  }

  /**
   * 写入数据
   * @param {*} item - 要写入的数据
   */
  push(item) {
    this.buffer[this.head] = item

    // 移动写入指针
    this.head = (this.head + 1) % this.capacity

    // 如果缓冲区已满，移动读取指针
    if (this.isFull) {
      this.tail = (this.tail + 1) % this.capacity
    } else {
      this.size++
    }

    // 检查是否已满
    if (this.size === this.capacity) {
      this.isFull = true
    }
  }

  /**
   * 读取最新数据（不移除）
   * @param {number} index - 相对于最新的偏移量（0=最新）
   * @returns {*} 数据项
   */
  peekLatest(index = 0) {
    if (index >= this.size) {
      return undefined
    }

    const actualIndex = (this.head - 1 - index + this.capacity) % this.capacity
    return this.buffer[actualIndex]
  }

  /**
   * 读取最旧数据（不移除）
   * @param {number} index - 相对于最旧的偏移量（0=最旧）
   * @returns {*} 数据项
   */
  peekOldest(index = 0) {
    if (index >= this.size) {
      return undefined
    }

    const actualIndex = (this.tail + index) % this.capacity
    return this.buffer[actualIndex]
  }

  /**
   * 获取指定范围的数据
   * @param {number} start - 起始索引（从最旧开始）
   * @param {number} end - 结束索引（不包含）
   * @returns {Array} 数据数组
   */
  getRange(start, end) {
    const result = []
    const length = Math.min(end, this.size) - start

    for (let i = 0; i < length; i++) {
      const index = (this.tail + start + i) % this.capacity
      result.push(this.buffer[index])
    }

    return result
  }

  /**
   * 获取最新的N个数据
   * @param {number} count - 数据数量
   * @returns {Array} 数据数组（从旧到新）
   */
  getLatest(count) {
    const actualCount = Math.min(count, this.size)
    const start = this.size - actualCount
    return this.getRange(start, this.size)
  }

  /**
   * 清空缓冲区
   */
  clear() {
    this.head = 0
    this.tail = 0
    this.size = 0
    this.isFull = false
  }

  /**
   * 获取当前大小
   * @returns {number} 数据数量
   */
  getSize() {
    return this.size
  }

  /**
   * 检查是否已满
   * @returns {boolean} 是否已满
   */
  isBufferFull() {
    return this.isFull
  }

  /**
   * 检查是否为空
   * @returns {boolean} 是否为空
   */
  isEmpty() {
    return this.size === 0
  }

  /**
   * 转换为数组（从旧到新）
   * @returns {Array} 数据数组
   */
  toArray() {
    return this.getRange(0, this.size)
  }

  /**
   * 获取统计信息
   * @returns {Object} 统计信息
   */
  getStats() {
    return {
      capacity: this.capacity,
      size: this.size,
      isFull: this.isFull,
      head: this.head,
      tail: this.tail,
      usage: (this.size / this.capacity * 100).toFixed(1) + '%'
    }
  }
}

/**
 * 数学工具类
 * 提供信号处理、统计计算、矩阵运算等数学函数
 */

export default class MathUtils {
  /**
   * 计算均值
   * @param {Array} data - 数据数组
   * @returns {number} 均值
   */
  static mean(data) {
    if (!data || data.length === 0) return 0
    const sum = data.reduce((acc, val) => acc + val, 0)
    return sum / data.length
  }

  /**
   * 计算标准差
   * @param {Array} data - 数据数组
   * @returns {number} 标准差
   */
  static std(data) {
    if (!data || data.length === 0) return 0
    const avg = this.mean(data)
    const squareDiffs = data.map(val => Math.pow(val - avg, 2))
    const avgSquareDiff = this.mean(squareDiffs)
    return Math.sqrt(avgSquareDiff)
  }

  /**
   * 计算最大值
   * @param {Array} data - 数据数组
   * @returns {number} 最大值
   */
  static max(data) {
    if (!data || data.length === 0) return 0
    return Math.max(...data)
  }

  /**
   * 计算最小值
   * @param {Array} data - 数据数组
   * @returns {number} 最小值
   */
  static min(data) {
    if (!data || data.length === 0) return 0
    return Math.min(...data)
  }

  /**
   * 计算极差
   * @param {Array} data - 数据数组
   * @returns {number} 极差
   */
  static range(data) {
    return this.max(data) - this.min(data)
  }

  /**
   * 计算均方根
   * @param {Array} data - 数据数组
   * @returns {number} 均方根
   */
  static rms(data) {
    if (!data || data.length === 0) return 0
    const squares = data.map(val => val * val)
    const avgSquares = this.mean(squares)
    return Math.sqrt(avgSquares)
  }

  /**
   * 计算过零率
   * @param {Array} data - 数据数组
   * @returns {number} 过零率 (0-1)
   */
  static zeroCrossingRate(data) {
    if (!data || data.length < 2) return 0
    let crossings = 0
    const mean = this.mean(data)

    for (let i = 1; i < data.length; i++) {
      if ((data[i - 1] - mean) * (data[i] - mean) < 0) {
        crossings++
      }
    }

    return crossings / (data.length - 1)
  }

  /**
   * Z-score 标准化
   * @param {Array} data - 数据数组
   * @returns {Array} 标准化后的数据
   */
  static zscore(data) {
    if (!data || data.length === 0) return []
    const avg = this.mean(data)
    const stdDev = this.std(data)

    if (stdDev === 0) return data.map(() => 0)
    return data.map(val => (val - avg) / stdDev)
  }

  /**
   * Min-Max 归一化
   * @param {Array} data - 数据数组
   * @param {number} min - 目标最小值 (默认0)
   * @param {number} max - 目标最大值 (默认1)
   * @returns {Array} 归一化后的数据
   */
  static minMax(data, min = 0, max = 1) {
    if (!data || data.length === 0) return []
    const dataMin = this.min(data)
    const dataMax = this.max(data)
    const range = dataMax - dataMin

    if (range === 0) return data.map(() => (min + max) / 2)
    return data.map(val => min + ((val - dataMin) / range) * (max - min))
  }

  /**
   * 3σ 原则异常值检测
   * @param {Array} data - 数据数组
   * @returns {Array} 过滤后的数据（移除异常值）
   */
  static filterOutliers3Sigma(data) {
    if (!data || data.length < 3) return data

    const avg = this.mean(data)
    const stdDev = this.std(data)
    const threshold = 3 * stdDev

    return data.filter(val => Math.abs(val - avg) <= threshold)
  }

  /**
   * 计算向量模长
   * @param {Array} vector - 向量数组 [x, y, z]
   * @returns {number} 模长
   */
  static vectorMagnitude(vector) {
    if (!vector || vector.length < 3) return 0
    return Math.sqrt(
      vector[0] * vector[0] +
      vector[1] * vector[1] +
      vector[2] * vector[2]
    )
  }

  /**
   * 计算两个向量的夹角
   * @param {Array} v1 - 向量1 [x, y, z]
   * @param {Array} v2 - 向量2 [x, y, z]
   * @returns {number} 夹角（度）
   */
  static vectorAngle(v1, v2) {
    if (!v1 || !v2 || v1.length < 3 || v2.length < 3) return 0

    const dot = v1[0] * v2[0] + v1[1] * v2[1] + v1[2] * v2[2]
    const mag1 = this.vectorMagnitude(v1)
    const mag2 = this.vectorMagnitude(v2)

    if (mag1 === 0 || mag2 === 0) return 0

    const cosAngle = dot / (mag1 * mag2)
    const angle = Math.acos(Math.min(Math.max(cosAngle, -1), 1))
    return angle * (180 / Math.PI)
  }

  /**
   * 卡尔曼滤波器
   * @param {number} measurement - 当前测量值
   * @param {Object} state - 上一状态 {x: 估计值, p: 估计误差}
   * @param {Object} config - 配置 {q: 过程噪声, r: 测量噪声}
   * @returns {Object} 新状态 {x: 估计值, p: 估计误差}
   */
  static kalmanFilter(measurement, state, config) {
    const { q = 0.01, r = 0.1 } = config

    // 预测
    const pPredicted = state.p + q

    // 更新
    const k = pPredicted / (pPredicted + r)  // 卡尔曼增益
    const xUpdated = state.x + k * (measurement - state.x)
    const pUpdated = (1 - k) * pPredicted

    return {
      x: xUpdated,
      p: pUpdated
    }
  }

  /**
   * 指数移动平均
   * @param {number} currentValue - 当前值
   * @param {number} lastValue - 上一次的值
   * @param {number} alpha - 平滑系数 (0-1)
   * @returns {number} 平滑后的值
   */
  static exponentialMovingAverage(currentValue, lastValue, alpha = 0.3) {
    return alpha * currentValue + (1 - alpha) * lastValue
  }

  /**
   * 限制数值范围
   * @param {number} value - 输入值
   * @param {number} min - 最小值
   * @param {number} max - 最大值
   * @returns {number} 限制后的值
   */
  static clamp(value, min, max) {
    return Math.min(Math.max(value, min), max)
  }

  /**
   * 线性插值
   * @param {number} start - 起始值
   * @param {number} end - 结束值
   * @param {number} t - 插值系数 (0-1)
   * @returns {number} 插值结果
   */
  static lerp(start, end, t) {
    return start + (end - start) * this.clamp(t, 0, 1)
  }

  /**
   * 计算数组的滑动窗口统计
   * @param {Array} data - 数据数组
   * @param {number} windowSize - 窗口大小
   * @returns {Array} 统计结果数组
   */
  static slidingWindowStats(data, windowSize) {
    const results = []

    for (let i = 0; i <= data.length - windowSize; i++) {
      const window = data.slice(i, i + windowSize)
      results.push({
        mean: this.mean(window),
        std: this.std(window),
        max: this.max(window),
        min: this.min(window)
      })
    }

    return results
  }
}

/**
 * 存储工具类
 * 封装 @system.storage，提供便捷的数据持久化方法
 */

import storage from '@system.storage'

export default class StorageUtil {
  /**
   * 获取数据
   * @param {string} key - 键名
   * @returns {Promise} 解析后的数据
   */
  static get(key) {
    return new Promise((resolve, reject) => {
      storage.get({
        key: key,
        success: (data) => {
          if (data) {
            try {
              resolve(JSON.parse(data))
            } catch (e) {
              resolve(data)
            }
          } else {
            resolve(null)
          }
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  /**
   * 设置数据
   * @param {string} key - 键名
   * @param {*} value - 值
   * @returns {Promise}
   */
  static set(key, value) {
    return new Promise((resolve, reject) => {
      const data = typeof value === 'object' ? JSON.stringify(value) : value
      storage.set({
        key: key,
        value: data,
        success: () => {
          resolve()
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  /**
   * 删除数据
   * @param {string} key - 键名
   * @returns {Promise}
   */
  static delete(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key: key,
        success: () => {
          resolve()
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  /**
   * 清空所有数据
   * @returns {Promise}
   */
  static clear() {
    return new Promise((resolve, reject) => {
      storage.clear({
        success: () => {
          resolve()
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  /**
   * 获取所有键
   * @returns {Promise}
   */
  static getAllKeys() {
    return new Promise((resolve, reject) => {
      storage.getAllKeys({
        success: (data) => {
          resolve(data)
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  /**
   * 检查键是否存在
   * @param {string} key - 键名
   * @returns {Promise<boolean>}
   */
  static async has(key) {
    try {
      const value = await this.get(key)
      return value !== null
    } catch (e) {
      return false
    }
  }

  /**
   * 获取带过期时间的数据
   * @param {string} key - 键名
   * @returns {Promise}
   */
  static async getWithExpiry(key) {
    try {
      const data = await this.get(key)
      if (!data) return null

      if (data.expiry && Date.now() > data.expiry) {
        await this.delete(key)
        return null
      }

      return data.value
    } catch (e) {
      return null
    }
  }

  /**
   * 设置带过期时间的数据
   * @param {string} key - 键名
   * @param {*} value - 值
   * @param {number} ttlMs - 过期时间（毫秒）
   * @returns {Promise}
   */
  static setWithExpiry(key, value, ttlMs) {
    const data = {
      value: value,
      expiry: Date.now() + ttlMs
    }
    return this.set(key, data)
  }

  /**
   * 批量获取
   * @param {Array} keys - 键名数组
   * @returns {Promise<Object>}
   */
  static async getMultiple(keys) {
    const results = {}
    for (const key of keys) {
      try {
        results[key] = await this.get(key)
      } catch (e) {
        results[key] = null
      }
    }
    return results
  }

  /**
   * 批量设置
   * @param {Object} data - 键值对对象
   * @returns {Promise}
   */
  static async setMultiple(data) {
    const promises = Object.entries(data).map(([key, value]) => {
      return this.set(key, value)
    })
    return Promise.all(promises)
  }

  /**
   * 原子操作：读取-修改-写入
   * @param {string} key - 键名
   * @param {Function} modifier - 修改函数
   * @returns {Promise} 修改后的值
   */
  static async update(key, modifier) {
    const current = await this.get(key)
    const updated = modifier(current)
    await this.set(key, updated)
    return updated
  }

  /**
   * 计数器自增
   * @param {string} key - 键名
   * @param {number} amount - 增量（默认1）
   * @returns {Promise<number>}
   */
  static async increment(key, amount = 1) {
    return this.update(key, (current) => {
      const num = typeof current === 'number' ? current : 0
      return num + amount
    })
  }

  /**
   * 列表追加
   * @param {string} key - 键名
   * @param {*} item - 要追加的项
   * @param {number} maxItems - 最大项数（默认100）
   * @returns {Promise<Array>}
   */
  static async append(key, item, maxItems = 100) {
    return this.update(key, (current) => {
      const list = Array.isArray(current) ? current : []
      list.push(item)
      if (list.length > maxItems) {
        list.shift()
      }
      return list
    })
  }

  /**
   * 获取存储使用情况
   * @returns {Promise<Object>}
   */
  static async getUsage() {
    try {
      const keys = await this.getAllKeys()
      let totalSize = 0

      for (const key of keys) {
        const value = await this.get(key)
        if (value) {
          totalSize += JSON.stringify(value).length
        }
      }

      return {
        keyCount: keys.length,
        totalSize: totalSize,
        totalSizeKB: (totalSize / 1024).toFixed(2)
      }
    } catch (e) {
      return {
        keyCount: 0,
        totalSize: 0,
        totalSizeKB: '0.00'
      }
    }
  }
}

/**
 * 传感器管理器
 * 负责传感器的初始化、启停、数据回调管理
 * 实现低功耗优化和异常处理
 */

import sensor from '@system.sensor'
import { SENSOR_CONFIG, POWER_CONFIG, ERROR_CODES } from '../config/constants'

export default class SensorManager {
  constructor() {
    // 传感器状态
    this.state = {
      isRunning: false,
      accelerometerId: null,
      gyroscopeId: null,
      lastUpdate: 0,
      errorCode: null,
      errorMessage: null
    }

    // 数据回调
    this.onDataCallback = null
    this.onErrorCallback = null

    // 采样率配置
    this.samplingRate = POWER_CONFIG.NORMAL_SAMPLE_RATE
    this.isLowPowerMode = false

    // 数据缓存
    this.accelData = { x: 0, y: 0, z: 0 }
    this.gyroData = { x: 0, y: 0, z: 0 }

    // 性能统计
    this.stats = {
      totalReads: 0,
      errorCount: 0,
      avgReadTime: 0
    }
  }

  /**
   * 设置数据回调
   * @param {Function} callback - 数据回调函数
   */
  setDataCallback(callback) {
    this.onDataCallback = callback
  }

  /**
   * 设置错误回调
   * @param {Function} callback - 错误回调函数
   */
  setErrorCallback(callback) {
    this.onErrorCallback = callback
  }

  /**
   * 启动传感器
   * @param {Object} options - 配置选项
   * @returns {Promise<boolean>} 是否成功启动
   */
  async start(options = {}) {
    if (this.state.isRunning) {
      console.log('传感器已在运行中')
      return true
    }

    try {
      // 合并配置
      const config = {
        samplingRate: options.samplingRate || this.samplingRate,
        ...options
      }

      // 启动加速度计
      await this.startAccelerometer(config.samplingRate)

      // 启动陀螺仪
      await this.startGyroscope(config.samplingRate)

      this.state.isRunning = true
      this.state.errorCode = null
      this.state.errorMessage = null

      console.log(`传感器启动成功，采样率: ${config.samplingRate}Hz`)
      return true

    } catch (error) {
      this.state.errorCode = ERROR_CODES.SENSOR_INIT_FAILED
      this.state.errorMessage = error.message || '传感器启动失败'
      this.stats.errorCount++

      if (this.onErrorCallback) {
        this.onErrorCallback(this.state.errorCode, this.state.errorMessage)
      }

      console.error('传感器启动失败:', error)
      return false
    }
  }

  /**
   * 启动加速度计
   * @param {number} rate - 采样率 (Hz)
   */
  startAccelerometer(rate) {
    return new Promise((resolve, reject) => {
      const interval = Math.round(1000 / rate)  // 转换为毫秒

      sensor.subscribeAccelerometer({
        interval: interval,
        success: (data) => {
          this.accelData = {
            x: data.x || 0,
            y: data.y || 0,
            z: data.z || 0
          }
          this.state.lastUpdate = Date.now()
          this.stats.totalReads++
          this.notifyDataCallback()
        },
        fail: (data, code) => {
          console.error('加速度计错误:', code, data)
          reject(new Error(`加速度计错误: ${code}`))
        }
      })

      // 延迟检查是否启动成功
      setTimeout(() => {
        if (this.state.lastUpdate > 0) {
          resolve()
        } else {
          resolve()  // 假设启动成功，等待数据
        }
      }, 100)
    })
  }

  /**
   * 启动陀螺仪
   * @param {number} rate - 采样率 (Hz)
   */
  startGyroscope(rate) {
    return new Promise((resolve, reject) => {
      const interval = Math.round(1000 / rate)

      sensor.subscribeGyroscope({
        interval: interval,
        success: (data) => {
          this.gyroData = {
            x: data.x || 0,
            y: data.y || 0,
            z: data.z || 0
          }
          this.notifyDataCallback()
        },
        fail: (data, code) => {
          console.error('陀螺仪错误:', code, data)
          reject(new Error(`陀螺仪错误: ${code}`))
        }
      })

      setTimeout(() => {
        resolve()
      }, 100)
    })
  }

  /**
   * 停止传感器
   */
  stop() {
    if (!this.state.isRunning) {
      return
    }

    try {
      // 取消加速度计订阅
      sensor.unsubscribeAccelerometer()

      // 取消陀螺仪订阅
      sensor.unsubscribeGyroscope()

      this.state.isRunning = false
      this.state.accelerometerId = null
      this.state.gyroscopeId = null

      console.log('传感器已停止')

    } catch (error) {
      console.error('停止传感器失败:', error)
    }
  }

  /**
   * 通知数据回调
   */
  notifyDataCallback() {
    if (this.onDataCallback) {
      const data = this.getLatestData()
      this.onDataCallback(data)
    }
  }

  /**
   * 获取最新数据
   * @returns {Object} 传感器数据
   */
  getLatestData() {
    return {
      accelerometer: { ...this.accelData },
      gyroscope: { ...this.gyroData },
      timestamp: this.state.lastUpdate
    }
  }

  /**
   * 切换低功耗模式
   * @param {boolean} enabled - 是否启用
   */
  async setLowPowerMode(enabled) {
    if (this.isLowPowerMode === enabled) {
      return
    }

    this.isLowPowerMode = enabled
    this.samplingRate = enabled
      ? POWER_CONFIG.LOW_POWER_SAMPLE_RATE
      : POWER_CONFIG.NORMAL_SAMPLE_RATE

    if (this.state.isRunning) {
      // 重启传感器以应用新的采样率
      this.stop()
      await this.start({ samplingRate: this.samplingRate })
    }

    console.log(`低功耗模式: ${enabled ? '开启' : '关闭'}`)
  }

  /**
   * 检查传感器状态
   * @returns {Object} 状态信息
   */
  getState() {
    return {
      ...this.state,
      samplingRate: this.samplingRate,
      isLowPowerMode: this.isLowPowerMode,
      stats: { ...this.stats }
    }
  }

  /**
   * 检查传感器是否正常工作
   * @returns {boolean} 是否正常
   */
  isHealthy() {
    if (!this.state.isRunning) return false

    // 检查最近是否有数据更新
    const timeSinceLastUpdate = Date.now() - this.state.lastUpdate
    return timeSinceLastUpdate < 1000  // 1秒内有数据更新
  }

  /**
   * 重置统计信息
   */
  resetStats() {
    this.stats = {
      totalReads: 0,
      errorCount: 0,
      avgReadTime: 0
    }
  }

  /**
   * 销毁资源
   */
  destroy() {
    this.stop()
    this.onDataCallback = null
    this.onErrorCallback = null
  }
}

/**
 * IMU 数据采集器
 * 负责收集、缓存、预处理传感器数据
 * 实现滑动窗口和特征提取
 */

import RingBuffer from '../utils/ring-buffer'
import MathUtils from '../utils/math-utils'
import { FEATURE_CONFIG, MODEL_CONFIG } from '../config/constants'

export default class IMUCollector {
  constructor(config = {}) {
    // 配置参数
    this.windowSize = config.windowSize || FEATURE_CONFIG.WINDOW_SIZE
    this.stride = config.stride || FEATURE_CONFIG.STRIDE
    this.featuresPerAxis = config.featuresPerAxis || FEATURE_CONFIG.FEATURES_PER_AXIS

    // 数据缓冲区（6轴：加速度XYZ + 陀螺仪XYZ）
    this.accelBuffer = {
      x: new RingBuffer(this.windowSize),
      y: new RingBuffer(this.windowSize),
      z: new RingBuffer(this.windowSize)
    }

    this.gyroBuffer = {
      x: new RingBuffer(this.windowSize),
      y: new RingBuffer(this.windowSize),
      z: new RingBuffer(this.windowSize)
    }

    // 时间戳缓冲区
    this.timestampBuffer = new RingBuffer(this.windowSize)

    // 计数器
    this.sampleCount = 0
    this.windowCount = 0

    // 数据标准化参数
    this.normalizationParams = {
      mean: new Array(6).fill(0),
      std: new Array(6).fill(1)
    }

    // 是否已收集足够数据
    this.isReady = false

    // 回调函数
    this.onWindowReady = null
  }

  /**
   * 添加新的传感器数据
   * @param {Object} data - 传感器数据 {accelerometer, gyroscope, timestamp}
   */
  addSample(data) {
    if (!data || !data.accelerometer || !data.gyroscope) {
      return
    }

    const { accelerometer, gyroscope, timestamp } = data

    // 添加到缓冲区
    this.accelBuffer.x.push(accelerometer.x || 0)
    this.accelBuffer.y.push(accelerometer.y || 0)
    this.accelBuffer.z.push(accelerometer.z || 0)

    this.gyroBuffer.x.push(gyroscope.x || 0)
    this.gyroBuffer.y.push(gyroscope.y || 0)
    this.gyroBuffer.z.push(gyroscope.z || 0)

    this.timestampBuffer.push(timestamp || Date.now())

    this.sampleCount++

    // 检查是否收集到一个完整的窗口
    if (this.sampleCount >= this.windowSize) {
      this.isReady = true
    }

    // 检查是否需要提取特征
    if (this.isReady && this.sampleCount % this.stride === 0) {
      this.windowCount++
      this.notifyWindowReady()
    }
  }

  /**
   * 通知窗口就绪
   */
  notifyWindowReady() {
    if (this.onWindowReady) {
      const features = this.extractFeatures()
      if (features) {
        this.onWindowReady(features)
      }
    }
  }

  /**
   * 提取特征
   * @returns {Array} 特征向量
   */
  extractFeatures() {
    if (!this.isReady) {
      return null
    }

    const features = []

    // 提取6个轴的数据
    const axes = [
      this.accelBuffer.x,
      this.accelBuffer.y,
      this.accelBuffer.z,
      this.gyroBuffer.x,
      this.gyroBuffer.y,
      this.gyroBuffer.z
    ]

    // 对每个轴提取统计特征
    for (const axisData of axes) {
      const data = axisData.toArray()

      if (data.length < this.windowSize) {
        return null  // 数据不足
      }

      // 提取特征
      features.push(MathUtils.mean(data))           // 均值
      features.push(MathUtils.std(data))            // 标准差
      features.push(MathUtils.max(data))            // 最大值
      features.push(MathUtils.min(data))            // 最小值
      features.push(MathUtils.range(data))          // 极差
      features.push(MathUtils.rms(data))            // 均方根
      features.push(MathUtils.zeroCrossingRate(data)) // 过零率
    }

    // 补零到固定维度（64维）
    while (features.length < MODEL_CONFIG.INPUT_SIZE) {
      features.push(0)
    }

    // 截断到固定维度
    features.length = MODEL_CONFIG.INPUT_SIZE

    // 数据标准化
    return this.normalizeFeatures(features)
  }

  /**
   * 标准化特征
   * @param {Array} features - 原始特征
   * @returns {Array} 标准化后的特征
   */
  normalizeFeatures(features) {
    // 使用 Z-score 标准化
    return MathUtils.zscore(features)
  }

  /**
   * 更新标准化参数
   * @param {Array} sampleFeatures - 样本特征
   */
  updateNormalizationParams(sampleFeatures) {
    if (!sampleFeatures || sampleFeatures.length === 0) {
      return
    }

    // 计算均值和标准差
    const numFeatures = sampleFeatures[0].length
    const numSamples = sampleFeatures.length

    for (let i = 0; i < numFeatures; i++) {
      const values = sampleFeatures.map(s => s[i])
      this.normalizationParams.mean[i] = MathUtils.mean(values)
      this.normalizationParams.std[i] = MathUtils.std(values) || 1
    }
  }

  /**
   * 获取当前窗口数据
   * @returns {Object} 窗口数据
   */
  getCurrentWindow() {
    return {
      accelerometer: {
        x: this.accelBuffer.x.toArray(),
        y: this.accelBuffer.y.toArray(),
        z: this.accelBuffer.z.toArray()
      },
      gyroscope: {
        x: this.gyroBuffer.x.toArray(),
        y: this.gyroBuffer.y.toArray(),
        z: this.gyroBuffer.z.toArray()
      },
      timestamps: this.timestampBuffer.toArray()
    }
  }

  /**
   * 获取原始数据（用于显示）
   * @returns {Object} 原始传感器数据
   */
  getRawData() {
    return {
      accelerometer: {
        x: this.accelBuffer.x.peekLatest(0) || 0,
        y: this.accelBuffer.y.peekLatest(0) || 0,
        z: this.accelBuffer.z.peekLatest(0) || 0
      },
      gyroscope: {
        x: this.gyroBuffer.x.peekLatest(0) || 0,
        y: this.gyroBuffer.y.peekLatest(0) || 0,
        z: this.gyroBuffer.z.peekLatest(0) || 0
      },
      sampleCount: this.sampleCount,
      isReady: this.isReady
    }
  }

  /**
   * 获取统计信息
   * @returns {Object} 统计信息
   */
  getStats() {
    return {
      sampleCount: this.sampleCount,
      windowCount: this.windowCount,
      isReady: this.isReady,
      bufferStats: {
        accelX: this.accelBuffer.x.getStats(),
        accelY: this.accelBuffer.y.getStats(),
        accelZ: this.accelBuffer.z.getStats(),
        gyroX: this.gyroBuffer.x.getStats(),
        gyroY: this.gyroBuffer.y.getStats(),
        gyroZ: this.gyroBuffer.z.getStats()
      }
    }
  }

  /**
   * 清空缓冲区
   */
  clear() {
    this.accelBuffer.x.clear()
    this.accelBuffer.y.clear()
    this.accelBuffer.z.clear()

    this.gyroBuffer.x.clear()
    this.gyroBuffer.y.clear()
    this.gyroBuffer.z.clear()

    this.timestampBuffer.clear()

    this.sampleCount = 0
    this.windowCount = 0
    this.isReady = false
  }

  /**
   * 设置窗口就绪回调
   * @param {Function} callback - 回调函数
   */
  setWindowReadyCallback(callback) {
    this.onWindowReady = callback
  }

  /**
   * 检查是否有足够的数据进行特征提取
   * @returns {boolean} 是否就绪
   */
  isReadyForInference() {
    return this.isReady && this.sampleCount >= this.windowSize
  }

  /**
   * 获取数据质量评估
   * @returns {Object} 质量评估结果
   */
  getDataQuality() {
    const accelData = this.accelBuffer.x.toArray()
    const gyroData = this.gyroBuffer.x.toArray()

    // 计算数据质量指标
    const accelVariance = MathUtils.std(accelData)
    const gyroVariance = MathUtils.std(gyroData)

    // 检查数据是否过于平稳（可能是传感器故障）
    const isStable = accelVariance < 0.1 && gyroVariance < 0.1

    // 检查数据是否有异常值
    const hasOutliers = accelData.some(v => Math.abs(v) > 100)

    return {
      quality: isStable ? 'poor' : (hasOutliers ? 'fair' : 'good'),
      accelVariance: accelVariance,
      gyroVariance: gyroVariance,
      isStable: isStable,
      hasOutliers: hasOutliers
    }
  }
}

/**
 * 轻量级神经网络
 * 纯 JavaScript 实现，无外部依赖
 * 专为手表端侧推理优化，支持 INT8 量化
 */

import MathUtils from '../utils/math-utils'
import { MODEL_CONFIG, QUANTIZATION_CONFIG } from '../config/constants'

export default class NeuralNetwork {
  /**
   * 构造函数
   * @param {Object} config - 网络配置
   */
  constructor(config = {}) {
    // 网络结构
    this.inputSize = config.inputSize || MODEL_CONFIG.INPUT_SIZE
    this.hiddenSize1 = config.hiddenSize1 || MODEL_CONFIG.HIDDEN_SIZE_1
    this.hiddenSize2 = config.hiddenSize2 || MODEL_CONFIG.HIDDEN_SIZE_2
    this.outputSize = config.outputSize || MODEL_CONFIG.OUTPUT_SIZE

    // 权重矩阵（使用 Float32Array 优化内存）
    this.weights = {
      // 输入层 -> 隐藏层1
      w1: null,  // [inputSize x hiddenSize1]
      b1: null,  // [hiddenSize1]

      // 隐藏层1 -> 隐藏层2
      w2: null,  // [hiddenSize1 x hiddenSize2]
      b2: null,  // [hiddenSize2]

      // 隐藏层2 -> 输出层
      w3: null,  // [hiddenSize2 x outputSize]
      b3: null   // [outputSize]
    }

    // 量化参数
    this.quantization = {
      enabled: QUANTIZATION_CONFIG.ENABLED,
      bits: QUANTIZATION_CONFIG.BITS,
      scale: QUANTIZATION_CONFIG.SCALE,
      zeroPoint: QUANTIZATION_CONFIG.ZERO_POINT
    }

    // 是否已初始化
    this.isInitialized = false

    // 内存使用统计
    this.memoryUsage = 0

    // 初始化网络
    this.initWeights()
  }

  /**
   * 初始化权重（Xavier 初始化）
   */
  initWeights() {
    // 输入层 -> 隐藏层1
    this.weights.w1 = this.xavierInit(this.inputSize, this.hiddenSize1)
    this.weights.b1 = new Float32Array(this.hiddenSize1).fill(0)

    // 隐藏层1 -> 隐藏层2
    this.weights.w2 = this.xavierInit(this.hiddenSize1, this.hiddenSize2)
    this.weights.b2 = new Float32Array(this.hiddenSize2).fill(0)

    // 隐藏层2 -> 输出层
    this.weights.w3 = this.xavierInit(this.hiddenSize2, this.outputSize)
    this.weights.b3 = new Float32Array(this.outputSize).fill(0)

    // 计算内存使用
    this.calculateMemoryUsage()

    this.isInitialized = true
    console.log(`神经网络初始化完成，内存使用: ${this.memoryUsage} bytes`)
  }

  /**
   * Xavier 初始化
   * @param {number} fanIn - 输入维度
   * @param {number} fanOut - 输出维度
   * @returns {Float32Array} 初始化后的权重
   */
  xavierInit(fanIn, fanOut) {
    const limit = Math.sqrt(6 / (fanIn + fanOut))
    const weights = new Float32Array(fanIn * fanOut)

    for (let i = 0; i < weights.length; i++) {
      weights[i] = (Math.random() * 2 - 1) * limit
    }

    return weights
  }

  /**
   * 前向传播
   * @param {Array} input - 输入特征向量
   * @returns {Array} 输出概率分布
   */
  forward(input) {
    if (!this.isInitialized) {
      throw new Error('网络未初始化')
    }

    if (input.length !== this.inputSize) {
      throw new Error(`输入维度错误: 期望 ${this.inputSize}，实际 ${input.length}`)
    }

    // 输入层 -> 隐藏层1 (ReLU)
    const hidden1 = this.denseReLU(input, this.weights.w1, this.weights.b1, this.inputSize, this.hiddenSize1)

    // 隐藏层1 -> 隐藏层2 (ReLU)
    const hidden2 = this.denseReLU(hidden1, this.weights.w2, this.weights.b2, this.hiddenSize1, this.hiddenSize2)

    // 隐藏层2 -> 输出层 (Softmax)
    const output = this.denseSoftmax(hidden2, this.weights.w3, this.weights.b3, this.hiddenSize2, this.outputSize)

    return output
  }

  /**
   * 全连接层 + ReLU 激活
   * @param {Array} input - 输入
   * @param {Float32Array} weights - 权重
   * @param {Float32Array} bias - 偏置
   * @param {number} inSize - 输入大小
   * @param {number} outSize - 输出大小
   * @returns {Array} 输出
   */
  denseReLU(input, weights, bias, inSize, outSize) {
    const output = new Array(outSize)

    for (let j = 0; j < outSize; j++) {
      let sum = bias[j]

      for (let i = 0; i < inSize; i++) {
        sum += input[i] * weights[i * outSize + j]
      }

      // ReLU 激活
      output[j] = Math.max(0, sum)
    }

    return output
  }

  /**
   * 全连接层 + Softmax 激活
   * @param {Array} input - 输入
   * @param {Float32Array} weights - 权重
   * @param {Float32Array} bias - 偏置
   * @param {number} inSize - 输入大小
   * @param {number} outSize - 输出大小
   * @returns {Array} 输出概率
   */
  denseSoftmax(input, weights, bias, inSize, outSize) {
    const logits = new Array(outSize)

    // 计算 logits
    for (let j = 0; j < outSize; j++) {
      let sum = bias[j]

      for (let i = 0; i < inSize; i++) {
        sum += input[i] * weights[i * outSize + j]
      }

      logits[j] = sum
    }

    // Softmax 归一化
    return this.softmax(logits)
  }

  /**
   * Softmax 函数
   * @param {Array} logits - 输入 logits
   * @returns {Array} 概率分布
   */
  softmax(logits) {
    // 找到最大值（数值稳定性）
    const maxLogit = Math.max(...logits)

    // 计算指数
    const expLogits = logits.map(l => Math.exp(l - maxLogit))

    // 计算总和
    const sumExp = expLogits.reduce((a, b) => a + b, 0)

    // 归一化
    return expLogits.map(e => e / sumExp)
  }

  /**
   * 预测类别
   * @param {Array} input - 输入特征
   * @returns {Object} 预测结果 {class: 类别索引, confidence: 置信度, probabilities: 概率分布}
   */
  predict(input) {
    const probabilities = this.forward(input)

    // 找到最大概率的类别
    let maxProb = -1
    let maxClass = 0

    for (let i = 0; i < probabilities.length; i++) {
      if (probabilities[i] > maxProb) {
        maxProb = probabilities[i]
        maxClass = i
      }
    }

    return {
      class: maxClass,
      confidence: maxProb,
      probabilities: probabilities
    }
  }

  /**
   * INT8 量化权重
   * @returns {Object} 量化后的权重
   */
  quantizeWeights() {
    if (!this.quantization.enabled) {
      return this.weights
    }

    const quantized = {}
    const scale = this.quantization.scale
    const zeroPoint = this.quantization.zeroPoint

    // 量化每个权重矩阵
    for (const key of Object.keys(this.weights)) {
      const original = this.weights[key]
      const quantizedArray = new Int8Array(original.length)

      for (let i = 0; i < original.length; i++) {
        // 量化：round(x / scale) + zeroPoint
        const quantizedValue = Math.round(original[i] / scale) + zeroPoint
        quantizedArray[i] = Math.max(-128, Math.min(127, quantizedValue))
      }

      quantized[key] = quantizedArray
    }

    return quantized
  }

  /**
   * 反量化权重
   * @param {Object} quantizedWeights - 量化后的权重
   * @returns {Object} 反量化后的权重
   */
  dequantizeWeights(quantizedWeights) {
    if (!this.quantization.enabled) {
      return quantizedWeights
    }

    const dequantized = {}
    const scale = this.quantization.scale
    const zeroPoint = this.quantization.zeroPoint

    for (const key of Object.keys(quantizedWeights)) {
      const quantized = quantizedWeights[key]
      const dequantizedArray = new Float32Array(quantized.length)

      for (let i = 0; i < quantized.length; i++) {
        // 反量化：(x - zeroPoint) * scale
        dequantizedArray[i] = (quantized[i] - zeroPoint) * scale
      }

      dequantized[key] = dequantizedArray
    }

    return dequantized
  }

  /**
   * 计算内存使用
   */
  calculateMemoryUsage() {
    let totalBytes = 0

    for (const key of Object.keys(this.weights)) {
      totalBytes += this.weights[key].byteLength
    }

    this.memoryUsage = totalBytes
  }

  /**
   * 获取模型大小（字节）
   * @returns {number} 模型大小
   */
  getModelSize() {
    return this.memoryUsage
  }

  /**
   * 获取模型大小（可读格式）
   * @returns {string} 模型大小
   */
  getModelSizeFormatted() {
    if (this.memoryUsage < 1024) {
      return `${this.memoryUsage} B`
    } else {
      return `${(this.memoryUsage / 1024).toFixed(2)} KB`
    }
  }

  /**
   * 导出模型权重
   * @returns {Object} 模型数据
   */
  exportModel() {
    return {
      config: {
        inputSize: this.inputSize,
        hiddenSize1: this.hiddenSize1,
        hiddenSize2: this.hiddenSize2,
        outputSize: this.outputSize
      },
      weights: this.quantization.enabled ? this.quantizeWeights() : this.weights,
      quantization: this.quantization,
      memoryUsage: this.memoryUsage
    }
  }

  /**
   * 导入模型权重
   * @param {Object} modelData - 模型数据
   */
  importModel(modelData) {
    if (!modelData || !modelData.config || !modelData.weights) {
      throw new Error('无效的模型数据')
    }

    // 验证配置
    const config = modelData.config
    if (config.inputSize !== this.inputSize ||
        config.hiddenSize1 !== this.hiddenSize1 ||
        config.hiddenSize2 !== this.hiddenSize2 ||
        config.outputSize !== this.outputSize) {
      throw new Error('模型配置不匹配')
    }

    // 导入权重
    if (modelData.quantization && modelData.quantization.enabled) {
      this.weights = this.dequantizeWeights(modelData.weights)
    } else {
      this.weights = modelData.weights
    }

    // 重新计算内存使用
    this.calculateMemoryUsage()

    console.log(`模型导入成功，大小: ${this.getModelSizeFormatted()}`)
  }

  /**
   * 加载预训练权重（示例）
   * 实际应用中应该从存储加载训练好的权重
   */
  loadPretrainedWeights() {
    // 这里加载用于演示的随机权重
    // 实际应用中应该使用训练好的模型
    console.log('加载预训练权重（演示模式）')

    // 使用更小的随机初始化（模拟训练后的权重）
    const scale = 0.1

    for (const key of Object.keys(this.weights)) {
      for (let i = 0; i < this.weights[key].length; i++) {
        this.weights[key][i] = (Math.random() * 2 - 1) * scale
      }
    }

    this.calculateMemoryUsage()
  }

  /**
   * 获取网络信息
   * @returns {Object} 网络信息
   */
  getInfo() {
    return {
      inputSize: this.inputSize,
      hiddenSize1: this.hiddenSize1,
      hiddenSize2: this.hiddenSize2,
      outputSize: this.outputSize,
      totalParams: this.countParameters(),
      modelSize: this.getModelSizeFormatted(),
      isInitialized: this.isInitialized,
      quantization: this.quantization.enabled
    }
  }

  /**
   * 计算参数数量
   * @returns {number} 参数总数
   */
  countParameters() {
    let count = 0

    for (const key of Object.keys(this.weights)) {
      count += this.weights[key].length
    }

    return count
  }

  /**
   * 重置网络（随机重新初始化）
   */
  reset() {
    this.initWeights()
  }
}

/**
 * 姿态分类器
 * 结合神经网络推理和后处理，提供稳定的姿态识别结果
 * 实现卡尔曼滤波、置信度阈值、异常检测
 */

import NeuralNetwork from './neural-network'
import MathUtils from '../utils/math-utils'
import {
  POSTURE_TYPES,
  POSTURE_NAMES,
  POSTURE_ICONS,
  POSTURE_COLORS,
  MODEL_CONFIG,
  INFERENCE_CONFIG
} from '../config/constants'

export default class PostureClassifier {
  constructor(config = {}) {
    // 神经网络模型
    this.model = new NeuralNetwork({
      inputSize: MODEL_CONFIG.INPUT_SIZE,
      hiddenSize1: MODEL_CONFIG.HIDDEN_SIZE_1,
      hiddenSize2: MODEL_CONFIG.HIDDEN_SIZE_2,
      outputSize: MODEL_CONFIG.OUTPUT_SIZE
    })

    // 分类配置
    this.config = {
      confidenceThreshold: config.confidenceThreshold || INFERENCE_CONFIG.CONFIDENCE_THRESHOLD,
      smoothingWindow: config.smoothingWindow || INFERENCE_CONFIG.SMOOTHING_WINDOW,
      enableKalman: config.enableKalman !== false
    }

    // 卡尔曼滤波器状态
    this.kalmanState = {
      x: 0,  // 估计值
      p: INFERENCE_CONFIG.KALMAN.ESTIMATION_ERROR
    }

    // 历史预测结果（用于平滑）
    this.predictionHistory = []

    // 当前姿态
    this.currentPosture = {
      type: POSTURE_TYPES.UNKNOWN,
      confidence: 0,
      rawClass: 0,
      timestamp: 0,
      isStable: false
    }

    // 姿态变化检测
    this.lastPostureType = POSTURE_TYPES.UNKNOWN
    this.postureChangeCallbacks = []

    // 性能统计
    this.stats = {
      totalInferences: 0,
      avgInferenceTime: 0,
      confidenceSum: 0
    }

    // 是否已初始化
    this.isInitialized = false
  }

  /**
   * 初始化分类器
   * @param {boolean} loadPretrained - 是否加载预训练权重
   */
  init(loadPretrained = true) {
    if (loadPretrained) {
      this.model.loadPretrainedWeights()
    }

    this.isInitialized = true
    console.log('姿态分类器初始化完成')
    console.log('模型信息:', this.model.getInfo())
  }

  /**
   * 分类姿态
   * @param {Array} features - 特征向量
   * @returns {Object} 分类结果
   */
  classify(features) {
    if (!this.isInitialized) {
      throw new Error('分类器未初始化')
    }

    const startTime = Date.now()

    // 神经网络推理
    const prediction = this.model.predict(features)

    // 后处理
    const result = this.postProcess(prediction)

    // 更新统计
    const inferenceTime = Date.now() - startTime
    this.updateStats(inferenceTime, result.confidence)

    return result
  }

  /**
   * 后处理
   * @param {Object} prediction - 神经网络原始预测
   * @returns {Object} 处理后的结果
   */
  postProcess(prediction) {
    // 1. 置信度阈值检查
    let classIndex = prediction.class
    let confidence = prediction.confidence

    if (confidence < this.config.confidenceThreshold) {
      classIndex = POSTURE_TYPES.UNKNOWN
      confidence = prediction.confidence
    }

    // 2. 卡尔曼滤波平滑
    if (this.config.enableKalman) {
      classIndex = this.applyKalmanFilter(classIndex, confidence)
    }

    // 3. 历史平滑
    this.predictionHistory.push(classIndex)
    if (this.predictionHistory.length > this.config.smoothingWindow) {
      this.predictionHistory.shift()
    }

    // 4. 多数投票
    const smoothedClass = this.majorityVote(this.predictionHistory)

    // 5. 检测姿态变化
    const postureType = this.classIndexToPostureType(smoothedClass)
    const postureName = POSTURE_NAMES[postureType]
    const postureIcon = POSTURE_ICONS[postureType]
    const postureColor = POSTURE_COLORS[postureType]

    // 检查姿态是否稳定
    const isStable = this.checkPostureStability()

    // 更新当前姿态
    this.currentPosture = {
      type: postureType,
      name: postureName,
      icon: postureIcon,
      color: postureColor,
      confidence: confidence,
      rawClass: prediction.class,
      rawConfidence: prediction.confidence,
      timestamp: Date.now(),
      isStable: isStable,
      probabilities: prediction.probabilities
    }

    // 检测姿态变化
    if (postureType !== this.lastPostureType) {
      this.notifyPostureChange(this.lastPostureType, postureType)
      this.lastPostureType = postureType
    }

    return this.currentPosture
  }

  /**
   * 卡尔曼滤波
   * @param {number} measurement - 测量值（类别索引）
   * @param {number} confidence - 置信度
   * @returns {number} 滤波后的类别索引
   */
  applyKalmanFilter(measurement, confidence) {
    // 使用置信度作为测量噪声的倒数
    const measurementNoise = 1 - confidence

    this.kalmanState = MathUtils.kalmanFilter(
      measurement,
      this.kalmanState,
      {
        q: INFERENCE_CONFIG.KALMAN.PROCESS_NOISE,
        r: measurementNoise * INFERENCE_CONFIG.KALMAN.MEASUREMENT_NOISE
      }
    )

    // 四舍五入到最近的类别
    return Math.round(this.kalmanState.x)
  }

  /**
   * 多数投票
   * @param {Array} history - 历史预测
   * @returns {number} 投票结果
   */
  majorityVote(history) {
    if (history.length === 0) {
      return POSTURE_TYPES.UNKNOWN
    }

    // 统计每个类别的出现次数
    const counts = {}
    for (const cls of history) {
      counts[cls] = (counts[cls] || 0) + 1
    }

    // 找到出现次数最多的类别
    let maxCount = 0
    let maxClass = history[0]

    for (const [cls, count] of Object.entries(counts)) {
      if (count > maxCount) {
        maxCount = count
        maxClass = parseInt(cls)
      }
    }

    return maxClass
  }

  /**
   * 检查姿态稳定性
   * @returns {boolean} 是否稳定
   */
  checkPostureStability() {
    if (this.predictionHistory.length < 3) {
      return false
    }

    // 检查最近几次预测是否一致
    const recentPredictions = this.predictionHistory.slice(-3)
    const allSame = recentPredictions.every(p => p === recentPredictions[0])

    return allSame
  }

  /**
   * 类别索引转换为姿态类型
   * @param {number} classIndex - 类别索引
   * @returns {string} 姿态类型
   */
  classIndexToPostureType(classIndex) {
    const types = [
      POSTURE_TYPES.STANDING,
      POSTURE_TYPES.SITTING,
      POSTURE_TYPES.WALKING,
      POSTURE_TYPES.RAISING_HAND,
      POSTURE_TYPES.FALLING
    ]

    return types[classIndex] || POSTURE_TYPES.UNKNOWN
  }

  /**
   * 检测摔倒
   * @param {Object} rawData - 原始传感器数据
   * @returns {boolean} 是否检测到摔倒
   */
  detectFalling(rawData) {
    if (!rawData || !rawData.accelerometer) {
      return false
    }

    const { x, y, z } = rawData.accelerometer
    const magnitude = MathUtils.vectorMagnitude([x, y, z])

    // 摔倒检测：加速度突然增大
    const fallingThreshold = 25  // m/s²（约2.5g）

    return magnitude > fallingThreshold
  }

  /**
   * 注册姿态变化回调
   * @param {Function} callback - 回调函数
   */
  onPostureChange(callback) {
    this.postureChangeCallbacks.push(callback)
  }

  /**
   * 通知姿态变化
   * @param {string} oldPosture - 旧姿态
   * @param {string} newPosture - 新姿态
   */
  notifyPostureChange(oldPosture, newPosture) {
    for (const callback of this.postureChangeCallbacks) {
      try {
        callback(oldPosture, newPosture)
      } catch (error) {
        console.error('姿态变化回调错误:', error)
      }
    }
  }

  /**
   * 更新统计信息
   * @param {number} inferenceTime - 推理时间
   * @param {number} confidence - 置信度
   */
  updateStats(inferenceTime, confidence) {
    this.stats.totalInferences++
    this.stats.confidenceSum += confidence

    // 更新平均推理时间
    const n = this.stats.totalInferences
    this.stats.avgInferenceTime = ((n - 1) * this.stats.avgInferenceTime + inferenceTime) / n
  }

  /**
   * 获取当前姿态
   * @returns {Object} 当前姿态信息
   */
  getCurrentPosture() {
    return { ...this.currentPosture }
  }

  /**
   * 获取统计信息
   * @returns {Object} 统计信息
   */
  getStats() {
    return {
      ...this.stats,
      averageConfidence: this.stats.totalInferences > 0
        ? this.stats.confidenceSum / this.stats.totalInferences
        : 0,
      modelInfo: this.model.getInfo()
    }
  }

  /**
   * 获取姿态信息
   * @param {string} postureType - 姿态类型
   * @returns {Object} 姿态信息
   */
  getPostureInfo(postureType) {
    return {
      type: postureType,
      name: POSTURE_NAMES[postureType] || '未知',
      icon: POSTURE_ICONS[postureType] || '❓',
      color: POSTURE_COLORS[postureType] || '#9ca3af'
    }
  }

  /**
   * 重置分类器
   */
  reset() {
    this.model.reset()
    this.kalmanState = { x: 0, p: INFERENCE_CONFIG.KALMAN.ESTIMATION_ERROR }
    this.predictionHistory = []
    this.currentPosture = {
      type: POSTURE_TYPES.UNKNOWN,
      confidence: 0,
      rawClass: 0,
      timestamp: 0,
      isStable: false
    }
    this.lastPostureType = POSTURE_TYPES.UNKNOWN
    this.stats = {
      totalInferences: 0,
      avgInferenceTime: 0,
      confidenceSum: 0
    }
  }

  /**
   * 导出模型
   * @returns {Object} 模型数据
   */
  exportModel() {
    return this.model.exportModel()
  }

  /**
   * 导入模型
   * @param {Object} modelData - 模型数据
   */
  importModel(modelData) {
    this.model.importModel(modelData)
  }
}

/**
 * 数据预处理器
 * 负责传感器数据的预处理、特征提取、数据增强
 * 实现异常值过滤、数据平滑、标准化
 */

import MathUtils from '../utils/math-utils'
import RingBuffer from '../utils/ring-buffer'
import { FEATURE_CONFIG, MODEL_CONFIG } from '../config/constants'

export default class DataPreprocessor {
  constructor(config = {}) {
    // 配置参数
    this.windowSize = config.windowSize || FEATURE_CONFIG.WINDOW_SIZE
    this.stride = config.stride || FEATURE_CONFIG.STRIDE
    this.featuresPerAxis = config.featuresPerAxis || FEATURE_CONFIG.FEATURES_PER_AXIS

    // 原始数据缓冲区
    this.rawBuffer = {
      accelX: new RingBuffer(this.windowSize * 2),  // 2倍窗口大小用于缓冲
      accelY: new RingBuffer(this.windowSize * 2),
      accelZ: new RingBuffer(this.windowSize * 2),
      gyroX: new RingBuffer(this.windowSize * 2),
      gyroY: new RingBuffer(this.windowSize * 2),
      gyroZ: new RingBuffer(this.windowSize * 2)
    }

    // 预处理后的数据缓冲区
    this.processedBuffer = new RingBuffer(this.windowSize * 2)

    // 异常值检测参数
    this.outlierThreshold = config.outlierThreshold || 3.0  // 3σ原则

    // 数据平滑参数
    this.smoothingAlpha = config.smoothingAlpha || 0.3  // 指数平滑系数

    // 标准化参数（在线更新）
    this.normalizationParams = {
      mean: new Array(6).fill(0),
      std: new Array(6).fill(1),
      count: 0
    }

    // 数据质量监控
    this.qualityStats = {
      totalSamples: 0,
      filteredSamples: 0,
      outlierCount: 0
    }
  }

  /**
   * 预处理传感器数据
   * @param {Object} rawData - 原始传感器数据
   * @returns {Object} 预处理后的数据
   */
  preprocess(rawData) {
    if (!rawData || !rawData.accelerometer || !rawData.gyroscope) {
      return null
    }

    this.qualityStats.totalSamples++

    // 1. 异常值检测和过滤
    const filteredData = this.filterOutliers(rawData)
    if (!filteredData) {
      this.qualityStats.filteredSamples++
      return null
    }

    // 2. 数据平滑
    const smoothedData = this.smoothData(filteredData)

    // 3. 添加到缓冲区
    this.addToBuffer(smoothedData)

    // 4. 更新标准化参数
    this.updateNormalizationParams(smoothedData)

    return smoothedData
  }

  /**
   * 异常值检测和过滤
   * @param {Object} data - 原始数据
   * @returns {Object|null} 过滤后的数据，如果数据异常则返回null
   */
  filterOutliers(data) {
    const { accelerometer, gyroscope } = data

    // 检查加速度数据
    const accelMagnitude = MathUtils.vectorMagnitude([
      accelerometer.x,
      accelerometer.y,
      accelerometer.z
    ])

    // 检查陀螺仪数据
    const gyroMagnitude = MathUtils.vectorMagnitude([
      gyroscope.x,
      gyroscope.y,
      gyroscope.z
    ])

    // 异常值阈值（根据传感器特性调整）
    const accelThreshold = 100  // m/s²（约10g）
    const gyroThreshold = 1000  // deg/s

    // 检查是否超出范围
    if (accelMagnitude > accelThreshold || gyroMagnitude > gyroThreshold) {
      this.qualityStats.outlierCount++
      console.warn('检测到异常传感器数据:', { accelMagnitude, gyroMagnitude })
      return null
    }

    // 检查NaN或Infinity
    if (isNaN(accelMagnitude) || isNaN(gyroMagnitude) ||
        !isFinite(accelMagnitude) || !isFinite(gyroMagnitude)) {
      this.qualityStats.outlierCount++
      console.warn('传感器数据包含NaN或Infinity')
      return null
    }

    return data
  }

  /**
   * 数据平滑（指数移动平均）
   * @param {Object} data - 原始数据
   * @returns {Object} 平滑后的数据
   */
  smoothData(data) {
    // 获取上一次的平滑值
    const lastSmoothed = this.processedBuffer.peekLatest(0)

    if (!lastSmoothed) {
      return data
    }

    const alpha = this.smoothingAlpha

    return {
      accelerometer: {
        x: MathUtils.exponentialMovingAverage(data.accelerometer.x, lastSmoothed.accelerometer.x, alpha),
        y: MathUtils.exponentialMovingAverage(data.accelerometer.y, lastSmoothed.accelerometer.y, alpha),
        z: MathUtils.exponentialMovingAverage(data.accelerometer.z, lastSmoothed.accelerometer.z, alpha)
      },
      gyroscope: {
        x: MathUtils.exponentialMovingAverage(data.gyroscope.x, lastSmoothed.gyroscope.x, alpha),
        y: MathUtils.exponentialMovingAverage(data.gyroscope.y, lastSmoothed.gyroscope.y, alpha),
        z: MathUtils.exponentialMovingAverage(data.gyroscope.z, lastSmoothed.gyroscope.z, alpha)
      },
      timestamp: data.timestamp
    }
  }

  /**
   * 添加数据到缓冲区
   * @param {Object} data - 平滑后的数据
   */
  addToBuffer(data) {
    this.rawBuffer.accelX.push(data.accelerometer.x)
    this.rawBuffer.accelY.push(data.accelerometer.y)
    this.rawBuffer.accelZ.push(data.accelerometer.z)
    this.rawBuffer.gyroX.push(data.gyroscope.x)
    this.rawBuffer.gyroY.push(data.gyroscope.y)
    this.rawBuffer.gyroZ.push(data.gyroscope.z)

    this.processedBuffer.push(data)
  }

  /**
   * 更新标准化参数（在线学习）
   * @param {Object} data - 新数据
   */
  updateNormalizationParams(data) {
    const values = [
      data.accelerometer.x,
      data.accelerometer.y,
      data.accelerometer.z,
      data.gyroscope.x,
      data.gyroscope.y,
      data.gyroscope.z
    ]

    this.normalizationParams.count++

    // 在线更新均值和标准差（Welford算法）
    const n = this.normalizationParams.count
    const delta = values.map((v, i) => v - this.normalizationParams.mean[i])

    for (let i = 0; i < 6; i++) {
      this.normalizationParams.mean[i] += delta[i] / n
      const delta2 = values[i] - this.normalizationParams.mean[i]
      this.normalizationParams.std[i] = Math.sqrt(
        ((n - 2) * this.normalizationParams.std[i] * this.normalizationParams.std[i] + delta[i] * delta2) / (n - 1)
      ) || 1
    }
  }

  /**
   * 提取特征
   * @returns {Array|null} 特征向量，如果数据不足则返回null
   */
  extractFeatures() {
    // 检查是否有足够的数据
    if (this.rawBuffer.accelX.getSize() < this.windowSize) {
      return null
    }

    const features = []

    // 提取6个轴的数据
    const axes = [
      this.rawBuffer.accelX.getLatest(this.windowSize),
      this.rawBuffer.accelY.getLatest(this.windowSize),
      this.rawBuffer.accelZ.getLatest(this.windowSize),
      this.rawBuffer.gyroX.getLatest(this.windowSize),
      this.rawBuffer.gyroY.getLatest(this.windowSize),
      this.rawBuffer.gyroZ.getLatest(this.windowSize)
    ]

    // 对每个轴提取统计特征
    for (const axisData of axes) {
      features.push(MathUtils.mean(axisData))           // 均值
      features.push(MathUtils.std(axisData))            // 标准差
      features.push(MathUtils.max(axisData))            // 最大值
      features.push(MathUtils.min(axisData))            // 最小值
      features.push(MathUtils.range(axisData))          // 极差
      features.push(MathUtils.rms(axisData))            // 均方根
      features.push(MathUtils.zeroCrossingRate(axisData)) // 过零率
    }

    // 补零到固定维度
    while (features.length < MODEL_CONFIG.INPUT_SIZE) {
      features.push(0)
    }

    // 截断到固定维度
    features.length = MODEL_CONFIG.INPUT_SIZE

    // 标准化
    return this.normalizeFeatures(features)
  }

  /**
   * 标准化特征
   * @param {Array} features - 原始特征
   * @returns {Array} 标准化后的特征
   */
  normalizeFeatures(features) {
    // 使用在线学习的参数进行标准化
    return features.map((val, i) => {
      const mean = this.normalizationParams.mean[i] || 0
      const std = this.normalizationParams.std[i] || 1
      return (val - mean) / std
    })
  }

  /**
   * 检查是否可以提取特征
   * @returns {boolean} 是否就绪
   */
  isReady() {
    return this.rawBuffer.accelX.getSize() >= this.windowSize
  }

  /**
   * 获取数据质量报告
   * @returns {Object} 质量报告
   */
  getQualityReport() {
    const total = this.qualityStats.totalSamples
    const outliers = this.qualityStats.outlierCount
    const filtered = this.qualityStats.filteredSamples

    return {
      totalSamples: total,
      outlierCount: outliers,
      filteredSamples: filtered,
      outlierRate: total > 0 ? (outliers / total * 100).toFixed(2) + '%' : '0%',
      filterRate: total > 0 ? (filtered / total * 100).toFixed(2) + '%' : '0%'
    }
  }

  /**
   * 获取缓冲区状态
   * @returns {Object} 缓冲区状态
   */
  getBufferStatus() {
    return {
      accelX: this.rawBuffer.accelX.getStats(),
      accelY: this.rawBuffer.accelY.getStats(),
      accelZ: this.rawBuffer.accelZ.getStats(),
      gyroX: this.rawBuffer.gyroX.getStats(),
      gyroY: this.rawBuffer.gyroY.getStats(),
      gyroZ: this.rawBuffer.gyroZ.getStats()
    }
  }

  /**
   * 清空缓冲区
   */
  clear() {
    this.rawBuffer.accelX.clear()
    this.rawBuffer.accelY.clear()
    this.rawBuffer.accelZ.clear()
    this.rawBuffer.gyroX.clear()
    this.rawBuffer.gyroY.clear()
    this.rawBuffer.gyroZ.clear()
    this.processedBuffer.clear()

    this.normalizationParams = {
      mean: new Array(6).fill(0),
      std: new Array(6).fill(1),
      count: 0
    }

    this.qualityStats = {
      totalSamples: 0,
      filteredSamples: 0,
      outlierCount: 0
    }
  }

  /**
   * 重置统计信息
   */
  resetStats() {
    this.qualityStats = {
      totalSamples: 0,
      filteredSamples: 0,
      outlierCount: 0
    }
  }
}

/**
 * Mock 传感器
 * 用于在AIoT IDE模拟器中测试姿态识别
 * 模拟不同姿态的传感器数据
 */

import { POSTURE_TYPES } from '../config/constants'

export default class MockSensor {
  constructor() {
    // 当前模拟的姿态
    this.currentPosture = POSTURE_TYPES.STANDING

    // 模拟配置
    this.config = {
      samplingRate: 50,  // Hz
      noiseLevel: 0.1,   // 噪声水平
      drift: 0.01        // 漂移
    }

    // 模拟状态
    this.state = {
      isRunning: false,
      timer: null,
      sampleCount: 0
    }

    // 回调函数
    this.onDataCallback = null
    this.onErrorCallback = null

    // 时间戳
    this.startTime = 0
    this.lastSampleTime = 0

    // 基础数据模板（不同姿态的典型数据）
    this.postureTemplates = {
      [POSTURE_TYPES.STANDING]: {
        accel: { x: 0, y: 0, z: 9.8 },      // 站立时Z轴为主
        gyro: { x: 0, y: 0, z: 0 }
      },
      [POSTURE_TYPES.SITTING]: {
        accel: { x: 0, y: -2, z: 9.6 },     // 坐下时略微前倾
        gyro: { x: 0, y: 0, z: 0 }
      },
      [POSTURE_TYPES.WALKING]: {
        accel: { x: 0.5, y: 0, z: 9.8 },    // 行走时有周期性摆动
        gyro: { x: 0, y: 0, z: 0.3 }
      },
      [POSTURE_TYPES.RAISING_HAND]: {
        accel: { x: 0, y: 9.8, z: 0 },      // 抬手时Y轴为主
        gyro: { x: 0, y: 0, z: 0 }
      },
      [POSTURE_TYPES.FALLING]: {
        accel: { x: 0, y: -5, z: 25 },      // 摔倒时加速度突变
        gyro: { x: 2, y: 0, z: 1 }
      }
    }
  }

  /**
   * 设置数据回调
   * @param {Function} callback - 数据回调函数
   */
  setDataCallback(callback) {
    this.onDataCallback = callback
  }

  /**
   * 设置错误回调
   * @param {Function} callback - 错误回调函数
   */
  setErrorCallback(callback) {
    this.onErrorCallback = callback
  }

  /**
   * 启动模拟传感器
   * @param {Object} options - 配置选项
   */
  start(options = {}) {
    if (this.state.isRunning) {
      console.log('Mock传感器已在运行中')
      return
    }

    // 合并配置
    this.config = {
      ...this.config,
      ...options
    }

    this.state.isRunning = true
    this.startTime = Date.now()
    this.lastSampleTime = 0
    this.state.sampleCount = 0

    // 启动定时器生成数据
    const interval = Math.round(1000 / this.config.samplingRate)
    this.state.timer = setInterval(() => {
      this.generateSample()
    }, interval)

    console.log(`Mock传感器启动，采样率: ${this.config.samplingRate}Hz`)
  }

  /**
   * 停止模拟传感器
   */
  stop() {
    if (!this.state.isRunning) {
      return
    }

    if (this.state.timer) {
      clearInterval(this.state.timer)
      this.state.timer = null
    }

    this.state.isRunning = false
    console.log('Mock传感器已停止')
  }

  /**
   * 生成一个采样点数据
   */
  generateSample() {
    if (!this.state.isRunning) {
      return
    }

    const now = Date.now()
    const elapsed = (now - this.startTime) / 1000  // 秒

    // 获取当前姿态的基础数据
    const template = this.postureTemplates[this.currentPosture]

    // 添加噪声和漂移
    const noise = () => (Math.random() - 0.5) * 2 * this.config.noiseLevel
    const drift = (t) => Math.sin(t * 0.1) * this.config.drift

    // 生成加速度数据
    const accel = {
      x: template.accel.x + noise() + drift(elapsed),
      y: template.accel.y + noise() + drift(elapsed),
      z: template.accel.z + noise() + drift(elapsed)
    }

    // 生成陀螺仪数据
    const gyro = {
      x: template.gyro.x + noise() + drift(elapsed),
      y: template.gyro.y + noise() + drift(elapsed),
      z: template.gyro.z + noise() + drift(elapsed)
    }

    // 行走时添加周期性摆动
    if (this.currentPosture === POSTURE_TYPES.WALKING) {
      const walkingFreq = 2  // Hz
      const walkingPhase = elapsed * walkingFreq * Math.PI * 2
      accel.x += Math.sin(walkingPhase) * 2
      accel.z += Math.cos(walkingPhase) * 0.5
      gyro.z += Math.cos(walkingPhase) * 0.5
    }

    // 摔倒时添加突变
    if (this.currentPosture === POSTURE_TYPES.FALLING) {
      const fallingPhase = elapsed % 2  // 2秒周期
      if (fallingPhase < 0.5) {
        // 摔倒瞬间
        accel.z = 25 + Math.random() * 5
        accel.y = -5 + Math.random() * 2
        gyro.x = 2 + Math.random()
      } else {
        // 恢复
        accel.z = 9.8 + Math.random() * 0.5
        accel.y = 0 + Math.random() * 0.5
        gyro.x = Math.random() * 0.2
      }
    }

    // 构建数据对象
    const data = {
      accelerometer: accel,
      gyroscope: gyro,
      timestamp: now
    }

    this.state.sampleCount++
    this.lastSampleTime = now

    // 通知回调
    if (this.onDataCallback) {
      this.onDataCallback(data)
    }
  }

  /**
   * 设置模拟姿态
   * @param {string} postureType - 姿态类型
   */
  setPosture(postureType) {
    if (this.postureTemplates[postureType]) {
      this.currentPosture = postureType
      console.log(`切换到姿态: ${postureType}`)
    } else {
      console.warn(`未知的姿态类型: ${postureType}`)
    }
  }

  /**
   * 获取当前姿态
   * @returns {string} 当前姿态类型
   */
  getCurrentPosture() {
    return this.currentPosture
  }

  /**
   * 获取所有可用的姿态
   * @returns {Array} 姿态类型数组
   */
  getAvailablePostures() {
    return Object.keys(this.postureTemplates)
  }

  /**
   * 模拟姿态变化
   * 按顺序循环切换姿态
   */
  cyclePosture() {
    const postures = this.getAvailablePostures()
    const currentIndex = postures.indexOf(this.currentPosture)
    const nextIndex = (currentIndex + 1) % postures.length
    this.setPosture(postures[nextIndex])
  }

  /**
   * 设置噪声水平
   * @param {number} level - 噪声水平 (0-1)
   */
  setNoiseLevel(level) {
    this.config.noiseLevel = Math.max(0, Math.min(1, level))
    console.log(`噪声水平设置为: ${this.config.noiseLevel}`)
  }

  /**
   * 设置采样率
   * @param {number} rate - 采样率 (Hz)
   */
  setSamplingRate(rate) {
    this.config.samplingRate = Math.max(1, Math.min(100, rate))

    // 如果正在运行，重启定时器
    if (this.state.isRunning) {
      this.stop()
      this.start()
    }

    console.log(`采样率设置为: ${this.config.samplingRate}Hz`)
  }

  /**
   * 获取统计信息
   * @returns {Object} 统计信息
   */
  getStats() {
    return {
      isRunning: this.state.isRunning,
      currentPosture: this.currentPosture,
      sampleCount: this.state.sampleCount,
      samplingRate: this.config.samplingRate,
      noiseLevel: this.config.noiseLevel,
      elapsedTime: this.state.isRunning
        ? (Date.now() - this.startTime) / 1000
        : 0
    }
  }

  /**
   * 销毁资源
   */
  destroy() {
    this.stop()
    this.onDataCallback = null
    this.onErrorCallback = null
  }
}

